export class ContentProvider{}export class SearchMatch{lineNumber;lineContent;columnNumber;constructor(t,e,n){this.lineNumber=t,this.lineContent=e,this.columnNumber=n}static comparator(t,e){return t.lineNumber-e.lineNumber}}export class SearchMatchExact{lineNumber;lineContent;columnNumber;matchLength;constructor(t,e,n,r){this.lineNumber=t,this.lineContent=e,this.columnNumber=n,this.matchLength=r}static comparator(t,e){return t.lineNumber-e.lineNumber||t.columnNumber-e.columnNumber}}export const contentAsDataURL=function(t,e,n,r,c=!0){return null==t||c&&t.length>1048576?null:"data:"+e+(r?";charset="+r:"")+(n?";base64":"")+","+t};